pub fn max(a: Vec<u64>) -> i64 {
    // Convert each u64 into an i64 (wrapping on overflow) and take the maximum
    // under signed comparison. If the input is empty, return -1.
    a.into_iter().map(|x| x as i64).max().unwrap_or(-1)
}

